INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(105182, 'ruRU', '', 'Легион отнял у меня оружие, так что будет только справедливо, если я возьму одно из их.', 24330),
(105184, 'ruRU', '', 'Высоко в небе! Узрите Он''ару! Дух орла вернулся!', 24330),
(105190, 'ruRU', '', 'Ох, эта старая байка? Конечно, могу рассказать ещё раз, если хочешь.$b$b<Рикет поднимает руки и начинает говорить низким голосом.>$b$bТак гласит легенда — он был огромен, как разоритель Скверны, с лицом, способным напугать даже старину Смертокрыла. Говорят, он потерял руку, создавая блестящего дроида Блингтрона. И заменил её ПАУЧЬИМ ТАНКОМ!$b$b<Рикет слегка посмеивается.>$b$bВообще-то последнюю достоверную весточку о нём я слышала от одного моряка, которого встретила в Кабестане. Пьяный в стельку, но мне кажется, в его словах была доля правды.$b$bЕго зовут Главный инженер Фут. Возможно, он сможет дать тебе настоящую зацепку, где найти изобретателя.', 24330),
(105213, 'ruRU', '', 'Мой дед, Гнопетто Биззфьюз, был великим изобретателем. Возможно, ты слышал о его единственном изобретении — дроиде Блингтроне.$b$bВсе хотели узнать его секреты создания внутренних схем Блингтрона, но он отказывался ими делиться.$b$bОн умер много лет назад, после того как море поднялось и поглотило его мастерскую. Сомневаюсь, что ты сможешь найти там что-то ещё, но если хочешь попробовать, можешь нырнуть и проверить.$b$bМожешь даже одолжить мой водолазный шлем, если хочешь.', 24330),
(105216, 'ruRU', '', 'Серебряный Союз на твоей стороне!', 24330),
(105218, 'ruRU', '', 'Слишком много времени прошло, $p. Слишком много!', 24330),
(105221, 'ruRU', '', '"Золотое яблоко" отлично настаивается, Слифна.', 24330),
(105222, 'ruRU', '', 'Всё ещё нужно починить этот жалкий предлог для повозки. Где там Джолфанг с той осью, а, Слиф?', 24330),
(105225, 'ruRU', '', '"Чёрное варево" заканчивается, Слифна. Если бы Мелба всё ещё была здесь, у нас никогда бы не кончались запасы.', 24330),
(105228, 'ruRU', '', 'Ищешь Мелбу? Я её ученица, но мою наставницу ты здесь не найдёшь.', 24330),
(105229, 'ruRU', '', 'Ты опоздал года на два, друг мой. Мелба мертва.', 24330),
(105231, 'ruRU', '', 'Идём, монах. Прогуляйся со мной.', 24330),
(105232, 'ruRU', '', 'Рецепты моей наставницы славились своим вкусом и крепостью. Мы отгружали бочки каждый день. "Золотое яблоко" — сладкое и терпкое. "Чёрное варево" — тёмное и горькое. "Сердце леса" — дубовое и яркое.', 24330),
(105233, 'ruRU', '', 'Морджирн, главный пивовар соседнего клана, завидовал мастерству моей наставницы. Он отправил отряд налётчиков, чтобы убить её и украсть рецепт.', 24330),
(105234, 'ruRU', '', 'Теперь рецепт у Морджирна, но мастерства ему не хватает. То, что ты пил у Врат Доблести — чистая бурда. В нём лишь малая доля ИСТИННОЙ силы Штормового варева.', 24330),
(105235, 'ruRU', '', 'Штормовое варево Мелбы было редчайшим и самым желанным из её рецептов. Говорят даже, что сам бог грома Один подавал этот напиток в своём чертоге защитников.', 24330),
(105253, 'ruRU', '', 'Свет меркнет...', 24330),
(105254, 'ruRU', '', 'Валхалас...', 24330),
(105255, 'ruRU', '', 'От твоей руки я встречаю свой конец...', 24330),
(105256, 'ruRU', '', 'Я падаю, посох разбит...', 24330),
(105257, 'ruRU', '', 'Суд ожидает...', 24330),
(105258, 'ruRU', '', 'Незваный гость!', 24330),
(105259, 'ruRU', '', 'Я прокляну твою душу!', 24330),
(105260, 'ruRU', '', 'Клянусь своим посохом!', 24330),
(105261, 'ruRU', '', 'Сегодня ты встретишь своих предков!', 24330),
(105262, 'ruRU', '', 'Я врайкул! Ты умрёшь!', 24330),
(105263, 'ruRU', '', 'Калдер — упрямый глупец...', 24330),
(105264, 'ruRU', '', 'У Эйнара нет предвидения...', 24330),
(105265, 'ruRU', '', 'Мне нужен чужеземец...', 24330),
(105266, 'ruRU', '', 'Это деяние я не могу совершить...', 24330),
(105267, 'ruRU', '', 'Я стану ярлом.', 24330),
(105272, 'ruRU', '', 'Что это такое?', 24330),
(105273, 'ruRU', '', 'Моя смерть ничего не остановит...', 24330),
(105284, 'ruRU', '', 'В чём задержка? Да идите уже!', 24330),
(105285, 'ruRU', '', 'Аааай!!! Ааай!!', 24330),
(105293, 'ruRU', '', 'Приближается ещё больше! Перехватите их!', 24330),
(105303, 'ruRU', '', 'Что?! У тебя вообще есть чувство долга — помогать товарищам-рыцарям?', 24330),
(105312, 'ruRU', '', 'Я помогала жителям деревни Дай-Ло оправиться от нашествия вредителей.$B$BЧэнь рассказывал мне истории о Шэнь-Цзинь Су, но я никак не ожидала, что черепаха окажется такой огромной!', 24330),
(105313, 'ruRU', '', 'Я слишком хорошо знаю боль и страдание от потери любимого человека. Именно поэтому я присоединилась к этой борьбе, да и варево здесь не так уж плохо.', 24330),
(105319, 'ruRU', '', 'Я отправлю тебя в бездну.', 24330);
